import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190119", "20190120", "20190121"]
segs = [("石家庄站", "永清站"), ("精河站", "中卫站")]
lines = ["西气东输二线", "西气东输三线"]

totals = {ln: 0.0 for ln in lines}
detail = {}
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            key = (row["起点站名"], row["终点站名"])
            if key in segs and row["管道划分"] in lines:
                v = abs(float(row["管道流量"]))
                totals[row["管道划分"]] += v
                detail.setdefault(row["管道划分"], {}).setdefault(key, []).append(v)

out = {"totals": totals, "detail": detail,
       "diff": totals["西气东输二线"] - totals["西气东输三线"]}
print(json.dumps(out, ensure_ascii=False, indent=1))

