import os
import csv
from pathlib import Path
from collections import deque

PIPELINE_FLOW_DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
NODE_FLOW_DIR = Path(os.environ["NODE_FLOW_DIR"])

date = "20191205"
pipeline_csv = PIPELINE_FLOW_DIR / f"{date}_pipeline.csv"
node_csv = NODE_FLOW_DIR / f"{date}_node.csv"

# Read pipeline segments
segments = []
with open(pipeline_csv, "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        segments.append({
            "source": row["起点站名"],
            "target": row["终点站名"],
            "pipeline": row["管道划分"],
            "flow": float(row["管道流量"]),
        })

# Read node types
node_types = {}
with open(node_csv, "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        key = (row["管道划分"], row["站名"])
        node_types[key] = row["类型"]

# Build adjacency (directed: source -> target)
adj = {}
for seg in segments:
    adj.setdefault(seg["source"], []).append(seg["target"])

# Find all sources (type == 气源)
sources = set()
for (pipeline, station), ntype in node_types.items():
    if ntype == "气源":
        sources.add(station)

print("=== All gas sources (气源) ===")
for s in sorted(sources):
    print(f"  {s}")

# BFS from each source to find shortest path to 高陵站
target = "高陵站"
print(f"\n=== Shortest paths to {target} ===")

for src in sorted(sources):
    # BFS
    queue = deque([(src, [src])])
    visited = {src}
    found = False
    while queue:
        node, path = queue.popleft()
        if node == target:
            print(f"  Source: {src}")
            print(f"  Path: {' -> '.join(path)}")
            print(f"  Hops: {len(path) - 1}")
            found = True
            break
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    if not found:
        print(f"  Source: {src} -> NOT REACHABLE to {target}")

# Also check: which sources can reach 高陵站 via 西气东输三线 only
print(f"\n=== Sources reachable to {target} via 西气东输三线 only ===")
adj_3 = {}
for seg in segments:
    if seg["pipeline"] == "西气东输三线":
        adj_3.setdefault(seg["source"], []).append(seg["target"])

for src in sorted(sources):
    queue = deque([(src, [src])])
    visited = {src}
    found = False
    while queue:
        node, path = queue.popleft()
        if node == target:
            print(f"  Source: {src}")
            print(f"  Path: {' -> '.join(path)}")
            print(f"  Hops: {len(path) - 1}")
            found = True
            break
        for neighbor in adj_3.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    if not found:
        print(f"  Source: {src} -> NOT REACHABLE via 西气东输三线")

# Check shared gateway: which stations are on ALL paths from sources to 高陵站
print(f"\n=== Shared gateway analysis ===")
all_paths = []
for src in sorted(sources):
    queue = deque([(src, [src])])
    visited = {src}
    while queue:
        node, path = queue.popleft()
        if node == target:
            all_paths.append(path)
            break
        for neighbor in adj.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

if all_paths:
    # Find common nodes (excluding source and target)
    common = set(all_paths[0])
    for p in all_paths[1:]:
        common &= set(p)
    common.discard(target)
    print(f"  Total paths found: {len(all_paths)}")
    print(f"  Common nodes (shared gateway): {common}")
else:
    print("  No paths found.")

