import os
import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])

files = ["20190223_pipeline.csv", "20190307_pipeline.csv"]
targets = ["西气东输二线", "冀宁线"]

daily = {}
for fname in files:
    path = DIR / fname
    sums = {t: 0.0 for t in targets}
    counts = {t: 0 for t in targets}
    with open(path, encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            name = row["管道划分"]
            if name in targets:
                sums[name] += abs(float(row["管道流量"]))
                counts[name] += 1
    daily[fname] = (sums, counts)

for fname, (sums, counts) in daily.items():
    print(fname)
    for t in targets:
        print(f"  {t}: sum={sums[t]:.3f}  segments={counts[t]}")

total = {t: 0.0 for t in targets}
for fname, (sums, counts) in daily.items():
    for t in targets:
        total[t] += sums[t]

print("TOTAL (20190223 + 20190307):")
for t in targets:
    print(f"  {t}: {total[t]:.3f}")

diff = total["西气东输二线"] - total["冀宁线"]
print(f"差值 (西气东输二线 - 冀宁线): {diff:.3f}")
print(f"西气东输二线 更高: {total['西气东输二线'] > total['冀宁线']}")

import os
from pathlib import Path
import csv
import statistics

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128", "20190129"]

# Collect flows for 川气东送 segments across 3 days
segment_data = {}  # (start, end) -> {date: flow}

for d in dates:
    csv_path = DIR / f"{d}_pipeline.csv"
    with open(csv_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row["管道划分"] == "川气东送":
                key = (row["起点站名"], row["终点站名"])
                if key not in segment_data:
                    segment_data[key] = {}
                segment_data[key][d] = float(row["管道流量"])

# Calculate standard deviation for each segment
results = []
for (start, end), flows in segment_data.items():
    values = list(flows.values())
    if len(values) == 3:
        std = statistics.stdev(values)
        results.append({
            "start": start,
            "end": end,
            "values": flows,
            "std": std
        })

# Sort by std descending
results.sort(key=lambda x: x["std"], reverse=True)

print("川气东送 管段输量标准差排名（2019-01-27 至 2019-01-29）：")
print("=" * 70)
for i, r in enumerate(results[:2], 1):
    print(f"\n第 {i} 名：{r['start']} → {r['end']}")
    print(f"  标准差: {r['std']:.3f}")
    for d in dates:
        print(f"  {d}: {r['values'][d]:.3f}")

print("\n" + "=" * 70)
print("全部管段标准差（供参考）：")
for r in results:
    print(f"  {r['start']} → {r['end']}: std={r['std']:.3f}")

